import{Z as t,e as i,f as n,a0 as a}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Maximizer","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/maximizer.md","filePath":"integrations/crm/maximizer.md","lastUpdated":1780377007000}'),r={name:"integrations/crm/maximizer.md"};function o(s,e,l,h,m,c){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="maximizer" tabindex="-1">Maximizer <a class="header-anchor" href="#maximizer" aria-label="Permalink to &quot;Maximizer&quot;">​</a></h1><p>Connect Maximizer to send enquiries to the records your team manages. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Maximizer as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-maximizer-api" tabindex="-1">Step 2. Connect to the Maximizer API <a class="header-anchor" href="#step-2-connect-to-the-maximizer-api" aria-label="Permalink to &quot;Step 2. Connect to the Maximizer API&quot;">​</a></h3><ol><li>Go to <a href="https://www.maximizer.com/support/crm-api/" target="_blank">Maximizer CRM API</a> and request access to their API.</li><li>When approved, you&#39;ll receive your details via email.</li><li>Enter your <strong>Username</strong> from Maximizer and paste in the <strong>Username</strong> field in Formie.</li><li>Enter your <strong>Password</strong> from Maximizer and paste in the <strong>Password</strong> field in Formie.</li><li>Copy the <strong>Web Access URL</strong> from Maximizer and paste in the <strong>Web Access URL</strong> field in Formie.</li><li>Copy the <strong>Database ID</strong> from Maximizer and paste in the <strong>Database ID</strong> field in Formie.</li><li>Copy the <strong>Vendor ID</strong> from Maximizer and paste in the <strong>Vendor ID</strong> field in Formie.</li><li>Copy the <strong>App Key</strong> from Maximizer and paste in the <strong>App Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the record types this integration exposes, then map the required destination fields using the variable picker. For a contact enquiry, map the visitor’s email and name where those fields are available. Use the requirements shown for your selected record type rather than assuming every CRM accepts the same fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the test record in the selected CRM destination. Check the mapped values and whether the integration created a record or updated an existing one as intended.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const p=t(r,[["render",o]]);export{g as __pageData,p as default};
